import json
import re

# Khai báo hằng số tương thích JSON
true = True
false = False
null = None

def to_dict(obj):
    if isinstance(obj, str):
        try:
            return json.loads(obj)
        except:
            return {}
    elif isinstance(obj, dict):
        return obj
    return {}

try:
    # Bơm dữ liệu từ Webhook Jira Automation
    payload = to_dict($exec)
    raw_str = json.dumps(payload)

    # 1. Trích xuất Agent ID (VD: 002)
    agent_match = re.search(r'Agent_ID:\s*(\d+)', raw_str)
    agent_id = agent_match.group(1) if agent_match else "002"

    # 2. Trích xuất Attacker IP (IPv4)
    ip_match = re.search(r'Attacker_IP:\s*([0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3})', raw_str)
    src_ip = ip_match.group(1).strip() if ip_match else ""

    # 3. Trích xuất Issue Key của Jira (VD: SA-60) để comment hoàn thành
    issue_key = payload.get("issue", {}).get("key", "")
    if not issue_key:
        key_match = re.search(r'"key":\s*"([^"]+)"', raw_str)
        issue_key = key_match.group(1) if key_match else "N/A"

    result = {
        "agent_id": agent_id,
        "src_ip": src_ip,
        "issue_key": issue_key
    }
    print(json.dumps(result))
except Exception as e:
    print(json.dumps({"error": str(e)}))

